#!/usr/bin/env python3
"""Generate contained Jekyll entry points for public position benchmarks."""

from __future__ import annotations

import argparse
import csv
import html
import re
from dataclasses import dataclass
from pathlib import Path


APP_ROOT = Path(__file__).resolve().parents[1]
DEFAULT_CATALOG = APP_ROOT / "benchmark/enrichment/form990_benchmark_position_catalog.csv"
GENERATED_MARKER = (
    "<!-- Generated by ceo-salary-benchmark/scripts/build_position_routes.py; "
    "do not edit. -->"
)
ROUTE_SOURCE_DIRECTORY = "position-routes"
SLUG_PATTERN = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
SUPPORT_LEVELS = {"primary", "exploratory", "hidden"}


@dataclass(frozen=True)
class PositionRoute:
    key: str
    label: str
    support: str
    slug: str

    @property
    def directory_name(self) -> str:
        return f"{self.slug}-salary-benchmark"

    @property
    def source_filename(self) -> str:
        return f"{self.directory_name}.html"


def _route_from_row(row: dict[str, str], row_number: int) -> PositionRoute:
    key = row.get("position_key", "").strip()
    label = row.get("page_label", "").strip() or row.get("label", "").strip()
    support = (row.get("support_level") or row.get("support") or "").strip().casefold()
    slug = row.get("route_slug", "").strip() or key.replace("_", "-")

    missing = [
        name
        for name, value in (("position_key", key), ("label", label), ("support", support))
        if not value
    ]
    if missing:
        raise ValueError(f"Catalog row {row_number} is missing: {', '.join(missing)}")
    if support not in SUPPORT_LEVELS:
        raise ValueError(f"Catalog row {row_number} has unknown support level {support!r}")
    if not SLUG_PATTERN.fullmatch(slug):
        raise ValueError(f"Catalog row {row_number} has invalid route slug {slug!r}")
    return PositionRoute(key=key, label=label, support=support, slug=slug)


def load_public_routes(catalog_path: Path) -> tuple[PositionRoute, ...]:
    """Return CEO plus supported primary positions, validating every catalog slug."""
    routes = [PositionRoute(key="ceo", label="CEO", support="primary", slug="ceo")]
    seen_keys = {"ceo": "synthetic CEO route"}
    seen_slugs = {"ceo": "synthetic CEO route"}

    with catalog_path.open(newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        if not reader.fieldnames:
            raise ValueError(f"Position catalog has no header: {catalog_path}")
        for row_number, row in enumerate(reader, start=2):
            route = _route_from_row(row, row_number)
            if route.key in seen_keys:
                raise ValueError(
                    f"Duplicate position key {route.key!r} in row {row_number}; "
                    f"already used by {seen_keys[route.key]}"
                )
            if route.slug in seen_slugs:
                raise ValueError(
                    f"Duplicate route slug {route.slug!r} in row {row_number}; "
                    f"already used by {seen_slugs[route.slug]}"
                )
            seen_keys[route.key] = f"catalog row {row_number}"
            seen_slugs[route.slug] = f"catalog row {row_number}"
            if route.support == "primary":
                routes.append(route)

    return tuple(routes)


def render_route_index(source_html: str, canonical_href: str) -> str:
    """Point every generated route at assets in the canonical app directory."""
    base_tag = f'<base href="{canonical_href}">'
    base_matches = list(re.finditer(r"<base\b[^>]*>", source_html, flags=re.IGNORECASE))
    if len(base_matches) > 1:
        raise ValueError("Canonical index contains more than one <base> element")
    if base_matches:
        start, end = base_matches[0].span()
        rendered = source_html[:start] + base_tag + source_html[end:]
    else:
        head_match = re.search(r"<head\b[^>]*>", source_html, flags=re.IGNORECASE)
        if not head_match:
            raise ValueError("Canonical index is missing a <head> element")
        rendered = source_html[: head_match.end()] + f"\n  {base_tag}" + source_html[head_match.end() :]

    doctype_match = re.match(r"(<!doctype\s+html>\s*)", rendered, flags=re.IGNORECASE)
    if not doctype_match:
        raise ValueError("Canonical index is missing an HTML doctype")
    return rendered[: doctype_match.end()] + GENERATED_MARKER + "\n" + rendered[doctype_match.end() :]


def render_position_route(source_html: str, canonical_href: str, route: PositionRoute) -> str:
    """Render a semantic route shell while keeping all assets canonical."""
    rendered = render_route_index(source_html, canonical_href)
    label = html.escape(route.label)
    replacements = (
        (
            r"<title>.*?</title>",
            f"<title>{label} Salary Benchmark · vetr.dev</title>",
            "document title",
        ),
        (
            r'(<meta\s+id="app-description"\s+name="description"\s+content=")[^"]*(">)',
            rf"\g<1>Interactive Rethink Priorities {label} salary benchmark explorer\g<2>",
            "description metadata",
        ),
        (
            r'(<h1\s+id="app-title"\s+aria-label=")[^"]*(")',
            rf"\g<1>{label} salary benchmark\g<2>",
            "app-title accessible label",
        ),
        (
            r'(<span\s+id="position-selected-label"[^>]*>).*?(</span>)',
            rf"\g<1>{label}\g<2>",
            "visible position title",
        ),
    )
    for pattern, replacement, description in replacements:
        rendered, count = re.subn(pattern, replacement, rendered, count=1, flags=re.IGNORECASE)
        if count != 1:
            raise ValueError(f"Canonical index is missing its {description}")

    canonical_url = f"https://vetr.dev/{route.directory_name}/"
    canonical_tag = f'<link rel="canonical" href="{canonical_url}">'
    canonical_pattern = r'<link\s+rel="canonical"\s+href="[^"]*"\s*/?>'
    canonical_matches = list(re.finditer(canonical_pattern, rendered, flags=re.IGNORECASE))
    if len(canonical_matches) > 1:
        raise ValueError("Canonical index contains more than one canonical link")
    if canonical_matches:
        start, end = canonical_matches[0].span()
        rendered = rendered[:start] + canonical_tag + rendered[end:]
    else:
        head_match = re.search(r"<head\b[^>]*>", rendered, flags=re.IGNORECASE)
        if not head_match:
            raise ValueError("Canonical index is missing a <head> element")
        rendered = rendered[: head_match.end()] + "\n  " + canonical_tag + rendered[head_match.end() :]

    front_matter = (
        "---\n"
        f"permalink: /{route.directory_name}/\n"
        "layout: null\n"
        "---\n"
    )
    return front_matter + rendered


def build_routes(
    app_root: Path,
    catalog_path: Path,
    *,
    check: bool = False,
) -> tuple[Path, ...]:
    app_root = app_root.resolve()
    canonical_name = "ceo-salary-benchmark"
    if app_root.name != canonical_name:
        raise ValueError(f"Canonical app directory must be named {canonical_name!r}: {app_root}")

    source_path = app_root / "index.html"
    if not source_path.is_file():
        raise FileNotFoundError(f"Canonical index is missing: {source_path}")
    source_html = source_path.read_text(encoding="utf-8")
    routes_root = app_root / ROUTE_SOURCE_DIRECTORY
    targets: list[Path] = []
    for route in load_public_routes(catalog_path):
        if route.key == "ceo":
            continue
        target = routes_root / route.source_filename
        rendered = render_position_route(source_html, f"/{canonical_name}/", route)
        targets.append(target)
        if check:
            if not target.is_file() or target.read_text(encoding="utf-8") != rendered:
                raise RuntimeError(f"Generated position route is missing or stale: {target}")
            continue
        if target.exists() and GENERATED_MARKER not in target.read_text(encoding="utf-8"):
            raise FileExistsError(f"Refusing to overwrite a non-generated route: {target}")
        routes_root.mkdir(parents=True, exist_ok=True)
        if not target.exists() or target.read_text(encoding="utf-8") != rendered:
            target.write_text(rendered, encoding="utf-8")

    expected_targets = set(targets)
    if routes_root.is_dir():
        for candidate in routes_root.glob("*.html"):
            if candidate in expected_targets:
                continue
            content = candidate.read_text(encoding="utf-8")
            if GENERATED_MARKER not in content:
                raise FileExistsError(
                    f"Refusing to remove a non-generated route from {routes_root}: {candidate}"
                )
            if check:
                raise RuntimeError(f"Stale generated position route: {candidate}")
            candidate.unlink()

    return tuple(targets)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--catalog", type=Path, default=DEFAULT_CATALOG)
    parser.add_argument(
        "--check",
        action="store_true",
        help="Verify generated routes without writing them.",
    )
    return parser.parse_args()


def main() -> None:
    args = parse_args()
    targets = build_routes(APP_ROOT, args.catalog, check=args.check)
    action = "Verified" if args.check else "Generated"
    print(f"{action} {len(targets)} public position route(s).")


if __name__ == "__main__":
    main()
